#ifndef TERMINOLOGY_KEYIN_KEYSYMS_H_
#define TERMINOLOGY_KEYIN_KEYSYMS_H_ 1

#include <stddef.h>
#include <stdint.h>

/* X11 keysym names with a Unicode mapping. The table is generated by
 * gperf from keyin_keysyms.gperf at build time. */

struct keyin_keysym {
     int name;      /* offset in the gperf string pool */
     uint32_t cp;
};

/* Case-sensitive. str needs not be NUL-terminated; len is its length.
 * Returns NULL when str is not a known keysym name. */
const struct keyin_keysym *keyin_keysym_lookup(const char *str, size_t len);

#endif
